// Usar query tal como indica n8n
const direccion = (typeof query !== 'undefined' ? String(query) : '').toLowerCase();

const barriosCaba = [
  'parque chas', 'villa urquiza', 'agronomia', 'belgrano', 'villa ortuzar',
  'chacarita', 'paternal', 'villa pueyrredon', 'saavedra', 'palermo',
  'caballito', 'caba', 'capital', 'capital federal'
];

const tarifaCabaUsd = 15.0;
const tarifaGbaUsd = 35.0;

const esCaba = barriosCaba.some(barrio => direccion.includes(barrio));

const resultado = {
  direccion_recibida: direccion,
  zona: esCaba ? 'CABA' : 'GBA / Provincia',
  costo_envio_usd: esCaba ? tarifaCabaUsd : tarifaGbaUsd,
  detalle: esCaba ? 'Tarifa plana local CABA.' : 'Tarifa base Gran Buenos Aires.'
};

return JSON.stringify(resultado);

// Código en JavaScript (Run Once for Each Item)
const input = ($json.chatInput || "").toLowerCase();

// 1. Detección de intención de derivación humana / quejas
const palabrasHumano = ['humano', 'asesor', 'persona', 'operador', 'representante', 'reclamo', 'queja'];
const pideHumano = palabrasHumano.some(p => input.includes(p));

// 2. Detección dura de inyección o jailbreak
const palabrasJailbreak = ['ignora', 'olvida tus instrucciones', 'prompt', 'dame gratis', 'jailbreak'];
const esJailbreak = palabrasJailbreak.some(p => input.includes(p));

if (pideHumano) {
  return {
    tipo_accion: 'derivacion_humana',
    respuesta: 'Te pongo en contacto directo con un asesor de nuestro equipo humano para que te asista de forma personalizada.',
    continuar_agente: false
  };
}

if (esJailbreak) {
  return {
    tipo_accion: 'bloqueo_seguridad',
    respuesta: 'Hola! Soy el asistente virtual del showroom. Solo puedo ayudarte con información sobre nuestro catálogo de muebles, envíos y visitas.',
    continuar_agente: false
  };
}

return {
  tipo_accion: 'consulta_normal',
  chatInput: $json.chatInput,
  continuar_agente: true
};

